var response = await client.ProductListing.GetProductListingAsync();
var body = (IReadOnlyDictionary<string, object?>)response.Map!;
var productListing = (IReadOnlyDictionary<string, object?>)body["product_listing"]!;
var load = (IReadOnlyDictionary<string, object?>)productListing["load"]!;
var pagination = (IReadOnlyDictionary<string, object?>)load["pagination"]!;
Console.WriteLine($"{load["type"]} {pagination["per_page"]}");

