var response = await client.ProductListing.PatchProductListingAsync(new Dictionary<string, object?>
{
    ["product_listing"] = new Dictionary<string, object?>
    {
        ["sorting"] = new Dictionary<string, object?> { ["enabled"] = true, ["sort_by"] = "price_asc" },
        ["load"] = new Dictionary<string, object?> { ["pagination"] = new Dictionary<string, object?> { ["per_page"] = 24 } },
    },
});
var body = (IReadOnlyDictionary<string, object?>)response.Map!;
var productListing = (IReadOnlyDictionary<string, object?>)body["product_listing"]!;
var sorting = (IReadOnlyDictionary<string, object?>)productListing["sorting"]!;
Console.WriteLine($"{sorting["enabled"]} {sorting["sort_by"]}");
